# (state, golden_ascii, id) -- each canonical frame pinned to exact pixels.
CASES = [
    (KrabState(), GOLDEN_NOMINAL, "nominal"),
    (KrabState(legs=[('hold', 'extend', 'retract')] * 6), GOLDEN_WALKING, "walking"),
    (KrabState(controllers={'FRONT': True, 'LEFT': False, 'RIGHT': True}), GOLDEN_LEFT_DOWN, "left_down"),
    (KrabState(controllers={'FRONT': True, 'LEFT': False, 'RIGHT': False}, legs=[('disc', 'disc', 'disc')] * 6, role='UNKWN', pack_v=19.2), GOLDEN_ONLY_FRONT, "only_front"),
]


@pytest.mark.parametrize(
    "state, golden, case_id",
    CASES,
    ids=[c[2] for c in CASES],
)
def test_golden_frame(state, golden, case_id):
    got = render(state).to_ascii()
    if got != golden:
        # Compact first-diff message so a regression points straight at the row.
        g_rows, e_rows = got.split("\n"), golden.split("\n")
        for y, (gr, er) in enumerate(zip(g_rows, e_rows)):
            if gr != er:
                cols = [x for x in range(min(len(gr), len(er))) if gr[x] != er[x]]
                more = "..." if len(cols) > 8 else ""
                pytest.fail(
                    f"[{case_id}] first pixel-row mismatch at y={y} "
                    f"(cols {cols[:8]}{more}):\n"
                    f"  expected: {er}\n  got:      {gr}"
                )
        pytest.fail(
            f"[{case_id}] frame differs in shape: "
            f"{len(g_rows)} rows vs {len(e_rows)} expected"
        )


def test_golden_dims():
    # Sanity: every golden really is a full 64x128 frame (guards a truncated paste).
    for _state, golden, case_id in CASES:
        rows = golden.split("\n")
        assert len(rows) == 64, f"{case_id}: expected 64 rows, got {len(rows)}"
        assert all(len(r) == 128 for r in rows), f"{case_id}: a row is not 128 wide"


def test_goldens_are_distinct():
    # The four canonical frames must not be accidentally identical, which would
    # make the lock vacuous for one of the states.
    asciis = [g for _s, g, _i in CASES]
    assert len(set(asciis)) == len(asciis), "two goldens are identical"
